// The checked catalogue the pronoun trainer builds every task from.
//
// Nothing here is generated by a model and nothing is combined blindly: each
// verb says which kinds of object it takes (people, things), which sentence
// constructions it may appear in, and how it reads in natural Russian. A
// teacher chooses settings over MCP; the app only ever builds tasks out of
// this file, so a construction the learner has not met cannot slip in.
//
// Version 1 trains Nominativ + Akkusativ. The dative forms are kept so the
// checker can name «mir вместо mich» as a case error, and so Dativ can be
// added later as its own block — it is never switched on by itself.

export const TEMPLATE_VERSION = "pron-v1";

export const PRONOUN_IDS = ["ich", "du", "er", "sie_sg", "es", "wir", "ihr", "sie_pl", "Sie"] as const;
export type PronounId = typeof PRONOUN_IDS[number];

/** Person key shared by the German and Russian verb tables. */
export type PersonKey = "1s" | "2s" | "3s" | "1p" | "2p" | "3p";

export type PronounInfo = {
  id: PronounId;
  person: 1 | 2 | 3;
  number: "sg" | "pl";
  gender: "m" | "f" | "n" | null;
  polite: boolean;
  nom: string;
  acc: string;
  dat: string;
  /** Which row of a German verb table agrees with this subject. */
  de: PersonKey;
  /** Which row of a Russian verb table: «Вы» conjugates as «вы». */
  ru: PersonKey;
  ruNom: string;
  ruAcc: string;
  ruDat: string;
  ruPrep: string;
  /** How the learner sees it named in settings and statistics. */
  label: string;
};

