export type GermanForms = Record<PersonKey, string>;
export type RussianForms = Record<PersonKey, string>;

export type VerbInfo = {
  id: string;
  infinitive: string;
  ru: string;
  /** Präsens without the separable prefix. */
  present: GermanForms;
  prefix: string | null;
  case: "accusative";
  preposition: string | null;
  objects: ("person" | "thing")[];
  /** Sentence types this verb sounds natural in. */
  sentenceTypes: ("statement" | "question" | "negation")[];
  /** Whether «können + infinitive» reads naturally with it. */
  modal: boolean;
  ruPresent: RussianForms;
  /** Russian infinitive after «могу / можешь…». */
  ruInfinitive: string;
  /** The case the Russian object takes: the difference that needs its own explanation. */
  ruObject: "acc" | "dat" | "prep";
  /** Words that follow the Russian object: «беру его с собой». */
  ruAfter?: string;
  /** Russian and German government differ: the rule is shown before the first such task. */
  governmentNote?: string;
  /** The construction that has to be switched on before the verb can appear at all. */
  requires: Construction | null;
};

const MODAL_KOENNEN: GermanForms = { "1s": "kann", "2s": "kannst", "3s": "kann", "1p": "können", "2p": "könnt", "3p": "können" };
const RU_MOCH: RussianForms = { "1s": "могу", "2s": "можешь", "3s": "может", "1p": "можем", "2p": "можете", "3p": "могут" };

export const MODAL = { infinitive: "können", present: MODAL_KOENNEN, ruPresent: RU_MOCH };

function de(f1s: string, f2s: string, f3s: string, f1p: string, f2p: string, f3p: string): GermanForms {
  return { "1s": f1s, "2s": f2s, "3s": f3s, "1p": f1p, "2p": f2p, "3p": f3p };
}
const ru = de as (a: string, b: string, c: string, d: string, e: string, f: string) => RussianForms;

