export const NOUN_BY_ID: Record<string, NounInfo> = Object.fromEntries(NOUNS.map((n) => [n.id, n]));

/** The pronoun a German noun is replaced with — by its German gender. */
export function pronounForNoun(noun: NounInfo): PronounId {
  return noun.gender === "m" ? "er" : noun.gender === "f" ? "sie_sg" : noun.gender === "n" ? "es" : "sie_pl";
}

export function articleFor(noun: NounInfo, kase: "nom" | "acc"): string {
  if (noun.gender === "m") return kase === "nom" ? "der" : "den";
  if (noun.gender === "f") return "die";
  if (noun.gender === "n") return "das";
  return "die";
}

export const RU_THING_ACC: Record<NounInfo["ruGender"], string> = { m: "его", f: "её", n: "его", pl: "их" };

/** Every pronoun form the checker can recognise, by case. */
export function pronounForms() {
  return {
    nom: PRONOUN_IDS.map((id) => PRONOUNS[id].nom),
    acc: PRONOUN_IDS.map((id) => PRONOUNS[id].acc),
    dat: PRONOUN_IDS.map((id) => PRONOUNS[id].dat),
  };
}

/**
 * The blocks one task needs switched on. A task is drawn only when every one
 * of them is: a separable verb needs «separable» even inside a noun task.
 */
export function constructionsNeeded(verb: VerbInfo, kind: "people" | "noun", sentenceType: "statement" | "question" | "negation", modal: boolean): Construction[] {
  const needs: Construction[] = [sentenceType];
  if (modal) needs.push("modal");
  if (verb.prefix) needs.push("separable");
  if (verb.preposition) needs.push("prep_auf");
  if (kind === "noun") needs.push("noun_replacement");
  return needs;
}

/** Can this verb produce any task at all with these blocks on? */
export function verbUsable(verb: VerbInfo, constructions: Construction[]): boolean {
  const on = new Set(constructions);
  const kinds: ("people" | "noun")[] = [];
  if (verb.objects.includes("person")) kinds.push("people");
  if (verb.objects.includes("thing") && NOUNS.some((n) => n.verbs.includes(verb.id))) kinds.push("noun");
  for (const kind of kinds) {
    for (const type of ["statement", "question", "negation"] as const) {
      for (const modal of [false, true]) {
        if (modal && !verb.modal) continue;
        if (!modal && !verb.sentenceTypes.includes(type)) continue;
        if (constructionsNeeded(verb, kind, type, modal).every((c) => on.has(c))) return true;
      }
    }
  }
  return false;
}
